function applyBank(locale, bank) {
  if (bank.length !== ids.length) throw new Error(`${locale}: expected ${ids.length} rows, got ${bank.length}`);
  const file = path.join(quizDir, `${locale}.json`);
  const data = JSON.parse(fs.readFileSync(file, "utf8"));
  const questions = data.stages.flatMap((stage) => stage.questions);
  const byId = new Map(questions.map((question) => [question.id, question]));
  ids.forEach((id, index) => {
    const question = byId.get(id);
    const [prompt, answers] = bank[index];
    question.question = prompt;
    question.answers = answers;
  });
  fs.writeFileSync(file, `${JSON.stringify(data, null, 2)}\n`);
  console.log(`Rebuilt native Chef bank: ${locale}`);
}

for (const [locale, bank] of Object.entries(banks)) if (bank.length) applyBank(locale, bank);
